import { COLLECTION_CURSOR_DURATION, COLLECTION_CURSOR_FRAME_COUNT } from './collectionCursorFrames';

// WebKit can resolve animated cursor URLs correctly while displaying the
// keyword fallback in an iframe. Explicit updates keep its native cursor.
export function watchPreviewCollectionCursor(root) {
  const doc = root.ownerDocument;
  if (!doc.documentElement.classList.contains('home-glass-preview')) return () => {};
  const win = doc.defaultView;
  const pointer = win.matchMedia('(hover: hover) and (pointer: fine)');
  const motion = win.matchMedia('(prefers-reduced-motion: reduce)');
  const images = new Map();
  let target = null;
  let frame = 0;
  let started = 0;
  let lastIndex = -1;

  function warm(cursor) {
    const url = cursor.match(/url\("([^"]+)"\)/)?.[1];
    if (!url || images.has(url)) return;
    const image = new win.Image();
    image.src = url;
    images.set(url, image);
  }

  function stop() {
    win.cancelAnimationFrame(frame);
    target?.style.removeProperty('--collection-toggle-cursor');
    target = null;
    lastIndex = -1;
  }

  function tick(now) {
    if (!target?.isConnected || !pointer.matches || motion.matches || doc.hidden) return stop();
    const index = Math.floor(((now - started) % COLLECTION_CURSOR_DURATION) / COLLECTION_CURSOR_DURATION * COLLECTION_CURSOR_FRAME_COUNT);
    if (index !== lastIndex) {
      const style = win.getComputedStyle(target);
      const key = style.getPropertyValue('--collection-cursor-animation').trim().replace('collection-cursor-', '');
      const fallback = style.getPropertyValue(`--collection-${key}-cursor-start`).trim();
      const cursor = style.getPropertyValue(`--collection-${key}-frame-${index}`).trim();
      if (cursor && fallback) {
        // Retain a decoded arrow if a new frame is still loading.
        target.style.setProperty('--collection-toggle-cursor', cursor.replace(/pointer$/, fallback));
        for (let i = 0; i < COLLECTION_CURSOR_FRAME_COUNT; i += 1) {
          warm(style.getPropertyValue(`--collection-${key}-frame-${i}`));
        }
      }
      lastIndex = index;
    }
    frame = win.requestAnimationFrame(tick);
  }

  function enter(event) {
    const next = event.target.closest('[data-collection-toggle]');
    if (next === target) return;
    stop();
    if (!next || !root.contains(next) || event.pointerType === 'touch' || !pointer.matches || motion.matches) return;
    target = next;
    started = win.performance.now() - 320;
    tick(win.performance.now());
  }
  function leave(event) {
    if (target && !target.contains(event.relatedTarget)) stop();
  }
  root.addEventListener('pointerover', enter);
  root.addEventListener('pointerout', leave);
  win.addEventListener('blur', stop);
  doc.addEventListener('visibilitychange', stop);
  return () => {
    stop();
    root.removeEventListener('pointerover', enter);
    root.removeEventListener('pointerout', leave);
    win.removeEventListener('blur', stop);
    doc.removeEventListener('visibilitychange', stop);
    images.clear();
  };
}
